import pandas as pd


def _sig(city, tier):
    c = '' if pd.isna(city) else str(city)
    t = '' if pd.isna(tier) else str(tier)
    return c.rstrip(' ') + '|' + t.rstrip(' ')


def run(inputs: dict) -> dict:
    dim = inputs['DIM_MEMBER']
    stg = inputs['STG_MEMBER']

    # Work with a list of row-dicts so we can mutate "current" rows in place
    # and append newly inserted versions, mirroring the procedural logic.
    records = dim.to_dict('records')

    for _, s in stg.iterrows():
        mid = s['member_id']

        # locate the current row (is_current = 1) for this member, if any
        cur_idx = None
        for i, r in enumerate(records):
            if r['member_id'] == mid and r['is_current'] == 1:
                cur_idx = i
                break

        if cur_idx is None:
            records.append({
                'member_id': mid,
                'city': s['city'],
                'tier': s['tier'],
                'eff_start_date': s['update_date'],
                'eff_end_date': None,
                'is_current': 1,
            })
        else:
            c = records[cur_idx]
            if _sig(s['city'], s['tier']) != _sig(c['city'], c['tier']):
                c['eff_end_date'] = s['update_date']
                c['is_current'] = 0
                records.append({
                    'member_id': mid,
                    'city': s['city'],
                    'tier': s['tier'],
                    'eff_start_date': s['update_date'],
                    'eff_end_date': None,
                    'is_current': 1,
                })
            # else: signatures match -> no-op, current row stays untouched

    out = pd.DataFrame(
        records,
        columns=['member_id', 'city', 'tier', 'eff_start_date', 'eff_end_date', 'is_current'],
    )

    return {'dim_member_out': out}
